{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Warfarin, the closest 4-hydroxycoumarin analogue of the query, is reported to have nearly complete oral bioavailability, directly supporting F>=20% for acenocoumarol.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Terodiline showed a mean absolute oral bioavailability of 92% in healthy volunteers, supporting high F for a lipophilic aromatic drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Baclofen had an absolute oral bioavailability of 81.2% after a 20 mg oral dose, supporting high F for a small polar aromatic molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Diflunisal had an absolute bioavailability of 89.5% versus IV, supporting high F for an aromatic carboxylic acid.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Phenylbutyrate showed 78% oral bioavailability in patients, supporting high F for an aromatic ester/carboxylic acid-type molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Labetalol, a high-transfer analogue, had an oral bioavailability of 18% in a 70 kg human, below the 20% threshold, indicating that high first-pass metabolism can occur in some high-transfer molecules.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F>=20%): the query is acenocoumarol, a 4-hydroxycoumarin anticoagulant; warfarin's nearly complete oral bioavailability and multiple high-F analogues outweigh the sub-20% labetalol record, which is structurally distinct and variable.",
  "evidence_gaps": [
    "No direct acenocoumarol absolute bioavailability record is supplied.",
    "The C02 record reports warfarin but its associated SMILES is inconsistent with warfarin, adding uncertainty.",
    "Labetalol records straddle the 20% threshold, so first-pass metabolism cannot be entirely excluded for structurally different high-transfer molecules."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

